import { loadUser } from "./loader.js";

// id -> loadUser 的 Promise。
// 缓存 Promise（而非 resolve 后的值）是为了让并发同 id 的调用也只真取一次：
// 第一次调用同步建缓存并返回，后续调用在 await 之前就能命中。
const cache = new Map();

export async function getUser(id) {
  const hit = cache.get(id);
  if (hit) return hit;

  const pending = loadUser(id);
  cache.set(id, pending);

  // 真取失败不留在缓存里，避免一次失败把该 id 永久毒化。
  pending.catch(() => {
    if (cache.get(id) === pending) cache.delete(id);
  });

  return pending;
}

export function resetCache() {
  cache.clear();
}
